export const photo = (key: string): Photo => {
  const p = photos.find((x) => x.key === key);
  if (!p) throw new Error(`Unknown photo ${key}`);
  return p;
};
export const photosFor = (service: string) => photos.filter((p) => p.services.includes(service));
export const photosOf = (project: string) => photos.filter((p) => p.project === project);
